import json
async def main(args):
    """短路检查：无文件变更 或 变更全部在 wiki 目录下（主 Agent 已维护）→ 跳过整个维护流程。
    纯代码零 LLM 调用——比意图识别更前置，省 local-qwen 一次调用。"""
    calls = args.params.get("changed_calls") or []
    if isinstance(calls, str):
        try: calls = json.loads(calls)
        except Exception: calls = []
    if not calls:
        return {"has_code_changes": False, "wiki_touched": False, "reason": "本轮无文件变更"}
    files = []
    for c in calls:
        files.extend((c.get("changed_files") or []))
    def _norm(p):
        return str(p).replace("\\", "/").lstrip("./")
    code_files = [f.get("file", "") for f in files if not _norm(f.get("file", "")).startswith("agent/wiki/")]
    wiki_touched = any(_norm(f.get("file", "")).startswith("agent/wiki/") for f in files)
    return {"has_code_changes": bool(code_files),
            "wiki_touched": wiki_touched,
            "reason": "" if code_files else "本轮无代码文件变更"}

