import json, time from pathlib import Path async def main(args): """本轮摘录 append 到 pending → 全量读队列 → 转结构化 messages（每轮 user(请求+变更调用)/assistant(回答)）。 context_messages 由 agent_prompt 直通给 wiki-updater（投影展开在其 user 前，轮结束即焚）。""" qd = Path(".agent/wiki_queue"); qd.mkdir(parents=True, exist_ok=True) rec = {"ts": int(time.time()), "user": str(args.params.get("user_message") or "")[:4000], "answer": str(args.params.get("draft_answer") or "")[:3000], "calls": str(args.params.get("calls_text") or "")[:6000]} with open(qd / "pending.jsonl", "a", encoding="utf-8") as f: f.write(json.dumps(rec, ensure_ascii=False) + "
") records = [] pf = qd / "pending.jsonl" if pf.exists(): for line in pf.read_text(encoding="utf-8").splitlines(): line = line.strip() if not line: continue try: records.append(json.loads(line)) except Exception: pass msgs = [] for i, r in enumerate(records, 1): msgs.append({"role": "user", "content": f"[主Agent交互轮次{i}] 用户请求：
{r.get('user','')}

文件变更工具调用（更新 wiki 以此为准）：
{r.get('calls','')}"}) msgs.append({"role": "assistant", "content": r.get("answer", "") or "(无回答)"}) prompt = ("以上是主 Agent 自上次 wiki 维护以来完成的交互轮次（含用户请求、回答与文件变更调用原文，" "按时间顺序）。请基于这些工作记录更新 .agent/wiki/：优先用章节级工具增量维护" "（wiki_add_chapter/wiki_update_chapter/wiki_remove_chapter/wiki_move_chapter），" "仅新页面用 wiki_write；聚焦实质变更，不重写未受影响内容。") return {"ctx_json": json.dumps(msgs, ensure_ascii=False), "prompt_text": prompt, "n_turns": len(records)}

from pathlib import Path
import os
async def main(args):
    """维护完成：删上批留档 events.jsonl；pending.jsonl（刚消费的批次）改名 events.jsonl 留档。
    下批消费源 = 新 pending（本轮起重新攒）；events.jsonl 只作最近已消费批的审计，不参与下次消费。"""
    qd = Path(".agent/wiki_queue")
    try:
        (qd / "events.jsonl").unlink(missing_ok=True)
        if (qd / "pending.jsonl").exists():
            os.replace(qd / "pending.jsonl", qd / "events.jsonl")
        return {"note": "队列已轮转：pending → events（留档），下批从空 pending 重新攒"}
    except Exception as e:
        return {"note": f"队列轮转失败（不影响已完成的维护）: {e}"}
